def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Defect on the final round: no future to protect.
    if n >= 100:
        return 'D'

    # Reliable defector: punish consistently until very end.
    if n >= 6 and opp.count('D') >= 5 and opp_d * 5 >= n * 4:
        if n < 95:
            return 'D'
        return 'D'

    # Opponent never defects: cooperate, with rare probes to prevent pure exploitation.
    if opp_d == 0:
        if n >= 96:
            return 'D'
        if n >= 40 and n % 13 == 0:
            return 'D'
        return 'C'

    # Extract last up to 8 opponent moves.
    recent = opp[-8:]
    recent_d = recent.count('D')
    recent_c = len(recent) - recent_d

    # Strong recent defection: punish.
    if recent_d >= 6:
        return 'D'

    # Long mutual defection spiral: attempt occasional repair.
    if last_me == 'D' and last_opp == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and opp[i] == 'D':
                run += 1
            else:
                break
        if run >= 3:
            if rng.random() < 0.30:
                return 'C'
            return 'D'
        if recent_d >= 2:
            return 'D'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent defected while we cooperated: retaliate, but forgive isolated defections.
    if last_opp == 'D':
        # Count consecutive exploit streaks (my C, opp D).
        streak = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'C' and opp[i] == 'D':
                streak += 1
            else:
                break
        if streak >= 2 or recent_d >= 3:
            return 'D'
        # Isolated defection: forgive quickly to preserve cooperation.
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Opponent cooperated last.
    if last_me == 'D':
        # We just exploited; return to cooperation to avoid endless feud.
        if recent_c >= 3:
            return 'C'
        if rng.random() < 0.8:
            return 'C'
        return 'D'

    # Both cooperating. Preserve mutual cooperation; small late-game exploitation.
    if recent_c >= 6:
        if n >= 90 and opp_d > 0:
            return 'C'
        if n >= 60 and n % 17 == 0 and opp_d <= max(1, n // 20):
            return 'D'
        return 'C'

    # Mixed recent history: give a chance, mirror moderate patterns.
    if recent_d >= 3:
        return 'D'
    if recent_d >= 1:
        # Conciliatory move to restore cooperation after brief conflict.
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    return 'C'
